package main

import "fmt"

// Sum accepts zero or more ints; inside, nums is a []int.
func Sum(nums ...int) int {
	total := 0
	for _, n := range nums { // range over the collected slice
		total += n
	}
	return total
}

func main() {
	fmt.Println(Sum(1, 2, 3)) // three args -> 6
	fmt.Println(Sum())        // no args -> 0 (nums is nil)
	fmt.Println(Sum(10))      // one arg  -> 10
}

