package solution

func Max(nums ...int) (int, bool) {
	if len(nums) == 0 { // no arguments -> no maximum exists
		return 0, false
	}
	best := nums[0]            // safe: at least one element
	for _, n := range nums[1:] {
		if n > best {
			best = n
		}
	}
	return best, true
}

