func Max(nums ...int) (int, bool) {
	if len(nums) == 0 {
		return 0, false // no values -> tell the caller
	}
	best := nums[0]
	for _, n := range nums[1:] {
		if n > best {
			best = n
		}
	}
	return best, true
}

func Join(sep string, parts ...string) string {
	if len(parts) == 0 {
		return ""
	}
	var b strings.Builder
	for i, p := range parts {
		if i > 0 {
			b.WriteString(sep) // separator before every element except the first
		}
		b.WriteString(p)
	}
	return b.String()
}
